1	/**
2	 * @hive-mind-test-suite default
3	 *
4	 * Regression coverage for issue #2082, finding F1.
5	 *
6	 * `scripts/helm-release.mjs` ran every git command as a bare `await $\`...\``.
7	 * command-stream's `$` resolves with `.code` instead of throwing, so the
8	 * wrapping try/catch was decorative: `git checkout gh-pages` aborted on a dirty
9	 * tree, execution continued on main, `git push origin gh-pages` reported
10	 * "Everything up-to-date", and the script printed "released successfully!" and
11	 * exited 0. The public Helm repository stayed frozen at 0.38.8 (2025-12-11)
12	 * while CI stayed green for ~7 months.
13	 *
14	 * These tests pin the three properties that make that failure impossible:
15	 *   1. a failing command aborts the release (restored `set -e` semantics);
16	 *   2. the release never switches branches in the dirty release checkout;
17	 *   3. the published index is verified to contain the released version.
18	 */
19	
20	import assert from 'node:assert/strict';
21	
22	import { CommandFailedError, runStrict } from '../scripts/run-command.lib.mjs';
23	import { parseChartName, releaseHelmChart, updateChartVersion } from '../scripts/helm-release.lib.mjs';
24	
25	// --- runStrict restores `set -e` semantics -------------------------------
26	
27	{
28	  const ok = await runStrict('true', [], { runner: async () => ({ code: 0, stdout: '', stderr: '' }) });
29	  assert.equal(ok.code, 0, 'runStrict resolves on exit 0');
30	
31	  await assert.rejects(
32	    () => runStrict('git', ['checkout', 'gh-pages'], { runner: async () => ({ code: 1, stdout: '', stderr: 'Aborting' }) }),
33	    error => {
34	      assert.ok(error instanceof CommandFailedError, 'a non-zero exit throws CommandFailedError');
35	      assert.equal(error.code, 1);
36	      assert.match(error.message, /git checkout gh-pages/, 'the error names the failing command');
37	      return true;
38	    },
39	    'runStrict must throw on a non-zero exit code — this is the guarantee command-stream lacks'
40	  );
41	}
42	
43	// --- Chart.yaml helpers ---------------------------------------------------
44	
45	{
46	  const chart = 'apiVersion: v2\nname: hive-mind\nversion: 0.38.8\nappVersion: "0.38.8"\n';
47	  assert.equal(parseChartName(chart), 'hive-mind');
48	  const updated = updateChartVersion(chart, '2.8.3');
49	  assert.match(updated, /^version: 2\.8\.3$/m);
50	  assert.match(updated, /^appVersion: "2\.8\.3"$/m);
51	}
52	
53	// --- Test harness ---------------------------------------------------------
54	
55	const CHART_YAML = 'apiVersion: v2\nname: hive-mind\nversion: 0.38.8\nappVersion: "0.38.8"\n';
56	
57	/**
58	 * Build a fake filesystem plus a recording runner.
59	 * @param {{fail?: (command: string, args: string[]) => boolean, indexVersions?: string[]}} [options]
60	 */
61	function createHarness({ fail = () => false, indexVersions = ['2.8.3'] } = {}) {
62	  const files = new Map([['helm/hive-mind/Chart.yaml', CHART_YAML]]);
63	  const calls = [];
64	
65	  const fs = {
66	    readFileSync: path => {
67	      if (!files.has(path)) throw new Error(`ENOENT: ${path}`);
68	      return files.get(path);
69	    },
70	    writeFileSync: (path, content) => files.set(path, content),
71	    existsSync: path => files.has(path),
72	    copyFileSync: (from, to) => files.set(to, files.get(from) ?? ''),
73	    mkdirSync: () => {},
74	    rmSync: () => {},
75	  };
76	
77	  const runner = async (command, args = []) => {
78	    calls.push([command, ...args].join(' '));
79	    if (fail(command, args)) {
80	      return { code: 1, stdout: '', stderr: 'simulated failure' };
81	    }
82	    // `helm package` writes the chart archive.
83	    if (command === 'helm' && args[0] === 'package') {
84	      files.set('.helm-packages/hive-mind-2.8.3.tgz', 'archive');
85	    }
86	    // Reading the published index back out of git.
87	    if (command === 'git' && args.includes('show') && args.some(a => String(a).endsWith(':index.yaml'))) {
88	      const entries = indexVersions.map(v => `    - version: ${v}\n`).join('');
89	      return { code: 0, stdout: `apiVersion: v1\nentries:\n  hive-mind:\n${entries}`, stderr: '' };
90	    }
91	    return { code: 0, stdout: '', stderr: '' };
92	  };
93	
94	  return { files, calls, fs, runner, logger: { log() {}, error() {} } };
95	}
96	
97	const release = (harness, overrides = {}) =>
98	  releaseHelmChart({
99	    version: '2.8.3',
100	    helmRepoUrl: 'https://link-assistant.github.io/hive-mind',
101	    githubActor: 'github-actions',
102	    fs: harness.fs,
103	    runner: harness.runner,
104	    logger: harness.logger,
105	    ...overrides,
106	  });
107	
108	// --- 1. A failing command aborts the release ------------------------------
109	
110	{
111	  // The exact production failure: the gh-pages checkout fails.
112	  const harness = createHarness({ fail: (command, args) => command === 'git' && args.includes('worktree') && args.includes('add') });
113	
114	  await assert.rejects(
115	    () => release(harness),
116	    error => error instanceof CommandFailedError,
117	    'a failing git command must abort the release instead of falling through to "released successfully"'
118	  );
119	}
120	
121	{
122	  // A failing push must not be reported as a successful release.
123	  const harness = createHarness({ fail: (command, args) => command === 'git' && args.includes('push') });
124	  await assert.rejects(() => release(harness), CommandFailedError, 'a failing push must abort the release');
125	}
126	
127	{
128	  // `helm lint` failing must abort before anything is published.
129	  const harness = createHarness({ fail: command => command === 'helm' });
130	  await assert.rejects(() => release(harness), CommandFailedError, 'a failing helm command must abort the release');
131	  assert.ok(!harness.calls.some(call => call.includes('push')), 'nothing is pushed after a lint failure');
132	}
133	
134	// --- 2. The release never switches branches in the release checkout -------
135	
136	{
137	  const harness = createHarness();
138	  await release(harness);
139	
140	  const branchSwitches = harness.calls.filter(call => /^git checkout(?! --orphan)/.test(call));
141	  assert.deepEqual(branchSwitches, [], 'the release must not `git checkout` in the dirty release tree — this is what aborted in production');
142	
143	  assert.ok(
144	    harness.calls.some(call => call.startsWith('git worktree add')),
145	    'gh-pages is published from an isolated worktree'
146	  );
147	  assert.ok(
148	    harness.calls.some(call => call.startsWith('git worktree remove')),
149	    'the worktree is cleaned up'
150	  );
151	}
152	
153	// --- 3. The published index is verified ------------------------------------
154	
155	{
156	  const harness = createHarness({ indexVersions: ['0.38.8'] }); // push "succeeded" but the version is absent
157	  await assert.rejects(
158	    () => release(harness),
159	    error => {
160	      assert.match(error.message, /2\.8\.3/, 'the verification error names the missing version');
161	      return true;
162	    },
163	    'a push that does not land the new version must fail the job, not report success'
164	  );
165	}
166	
167	{
168	  const harness = createHarness({ indexVersions: ['0.38.8', '2.8.3'] });
169	  const result = await release(harness);
170	  assert.equal(result.version, '2.8.3');
171	  assert.equal(result.published, true, 'a release that lands in the index reports success');
172	}
173	
174	// --- 4. The chart archive is placed next to index.yaml --------------------
175	
176	{
177	  const harness = createHarness();
178	  await release(harness);
179	  const indexCall = harness.calls.find(call => call.startsWith('helm repo index'));
180	  assert.ok(indexCall, 'the repository index is regenerated');
181	  assert.ok(harness.files.has('.helm-gh-pages/hive-mind-2.8.3.tgz'), 'the .tgz is copied next to index.yaml so its download URL resolves (production emitted a .helm-packages/ URL)');
182	}
183	
184	console.log('helm-release-2082.test.mjs: all assertions passed');

