/**
 * @hive-mind-test-suite default
 *
 * Regression coverage for issue #2082, finding F1.
 *
 * `scripts/helm-release.mjs` ran every git command as a bare `await $\`...\``.
 * command-stream's `$` resolves with `.code` instead of throwing, so the
 * wrapping try/catch was decorative: `git checkout gh-pages` aborted on a dirty
 * tree, execution continued on main, `git push origin gh-pages` reported
 * "Everything up-to-date", and the script printed "released successfully!" and
 * exited 0. The public Helm repository stayed frozen at 0.38.8 (2025-12-11)
 * while CI stayed green for ~7 months.
 *
 * These tests pin the three properties that make that failure impossible:
 *   1. a failing command aborts the release (restored `set -e` semantics);
 *   2. the release never switches branches in the dirty release checkout;
 *   3. the published index is verified to contain the released version.
 */

import assert from 'node:assert/strict';

import { CommandFailedError, runStrict } from '../scripts/run-command.lib.mjs';
import { parseChartName, releaseHelmChart, updateChartVersion } from '../scripts/helm-release.lib.mjs';

// --- runStrict restores `set -e` semantics -------------------------------

{
  const ok = await runStrict('true', [], { runner: async () => ({ code: 0, stdout: '', stderr: '' }) });
  assert.equal(ok.code, 0, 'runStrict resolves on exit 0');

  await assert.rejects(
    () => runStrict('git', ['checkout', 'gh-pages'], { runner: async () => ({ code: 1, stdout: '', stderr: 'Aborting' }) }),
    error => {
      assert.ok(error instanceof CommandFailedError, 'a non-zero exit throws CommandFailedError');
      assert.equal(error.code, 1);
      assert.match(error.message, /git checkout gh-pages/, 'the error names the failing command');
      return true;
    },
    'runStrict must throw on a non-zero exit code — this is the guarantee command-stream lacks'
  );
}

// --- Chart.yaml helpers ---------------------------------------------------

{
  const chart = 'apiVersion: v2\nname: hive-mind\nversion: 0.38.8\nappVersion: "0.38.8"\n';
  assert.equal(parseChartName(chart), 'hive-mind');
  const updated = updateChartVersion(chart, '2.8.3');
  assert.match(updated, /^version: 2\.8\.3$/m);
  assert.match(updated, /^appVersion: "2\.8\.3"$/m);
}

// --- Test harness ---------------------------------------------------------

const CHART_YAML = 'apiVersion: v2\nname: hive-mind\nversion: 0.38.8\nappVersion: "0.38.8"\n';

/**
 * Build a fake filesystem plus a recording runner.
 * @param {{fail?: (command: string, args: string[]) => boolean, indexVersions?: string[]}} [options]
 */
function createHarness({ fail = () => false, indexVersions = ['2.8.3'] } = {}) {
  const files = new Map([['helm/hive-mind/Chart.yaml', CHART_YAML]]);
  const calls = [];

  const fs = {
    readFileSync: path => {
      if (!files.has(path)) throw new Error(`ENOENT: ${path}`);
      return files.get(path);
    },
    writeFileSync: (path, content) => files.set(path, content),
    existsSync: path => files.has(path),
    copyFileSync: (from, to) => files.set(to, files.get(from) ?? ''),
    mkdirSync: () => {},
    rmSync: () => {},
  };

  const runner = async (command, args = []) => {
    calls.push([command, ...args].join(' '));
    if (fail(command, args)) {
      return { code: 1, stdout: '', stderr: 'simulated failure' };
    }
    // `helm package` writes the chart archive.
    if (command === 'helm' && args[0] === 'package') {
      files.set('.helm-packages/hive-mind-2.8.3.tgz', 'archive');
    }
    // Reading the published index back out of git.
    if (command === 'git' && args.includes('show') && args.some(a => String(a).endsWith(':index.yaml'))) {
      const entries = indexVersions.map(v => `    - version: ${v}\n`).join('');
      return { code: 0, stdout: `apiVersion: v1\nentries:\n  hive-mind:\n${entries}`, stderr: '' };
    }
    return { code: 0, stdout: '', stderr: '' };
  };

  return { files, calls, fs, runner, logger: { log() {}, error() {} } };
}

const release = (harness, overrides = {}) =>
  releaseHelmChart({
    version: '2.8.3',
    helmRepoUrl: 'https://link-assistant.github.io/hive-mind',
    githubActor: 'github-actions',
    fs: harness.fs,
    runner: harness.runner,
    logger: harness.logger,
    ...overrides,
  });

// --- 1. A failing command aborts the release ------------------------------

{
  // The exact production failure: the gh-pages checkout fails.
  const harness = createHarness({ fail: (command, args) => command === 'git' && args.includes('worktree') && args.includes('add') });

  await assert.rejects(
    () => release(harness),
    error => error instanceof CommandFailedError,
    'a failing git command must abort the release instead of falling through to "released successfully"'
  );
}

{
  // A failing push must not be reported as a successful release.
  const harness = createHarness({ fail: (command, args) => command === 'git' && args.includes('push') });
  await assert.rejects(() => release(harness), CommandFailedError, 'a failing push must abort the release');
}

{
  // `helm lint` failing must abort before anything is published.
  const harness = createHarness({ fail: command => command === 'helm' });
  await assert.rejects(() => release(harness), CommandFailedError, 'a failing helm command must abort the release');
  assert.ok(!harness.calls.some(call => call.includes('push')), 'nothing is pushed after a lint failure');
}

// --- 2. The release never switches branches in the release checkout -------

{
  const harness = createHarness();
  await release(harness);

  const branchSwitches = harness.calls.filter(call => /^git checkout(?! --orphan)/.test(call));
  assert.deepEqual(branchSwitches, [], 'the release must not `git checkout` in the dirty release tree — this is what aborted in production');

  assert.ok(
    harness.calls.some(call => call.startsWith('git worktree add')),
    'gh-pages is published from an isolated worktree'
  );
  assert.ok(
    harness.calls.some(call => call.startsWith('git worktree remove')),
    'the worktree is cleaned up'
  );
}

// --- 3. The published index is verified ------------------------------------

{
  const harness = createHarness({ indexVersions: ['0.38.8'] }); // push "succeeded" but the version is absent
  await assert.rejects(
    () => release(harness),
    error => {
      assert.match(error.message, /2\.8\.3/, 'the verification error names the missing version');
      return true;
    },
    'a push that does not land the new version must fail the job, not report success'
  );
}

{
  const harness = createHarness({ indexVersions: ['0.38.8', '2.8.3'] });
  const result = await release(harness);
  assert.equal(result.version, '2.8.3');
  assert.equal(result.published, true, 'a release that lands in the index reports success');
}

// --- 4. The chart archive is placed next to index.yaml --------------------

{
  const harness = createHarness();
  await release(harness);
  const indexCall = harness.calls.find(call => call.startsWith('helm repo index'));
  assert.ok(indexCall, 'the repository index is regenerated');
  assert.ok(harness.files.has('.helm-gh-pages/hive-mind-2.8.3.tgz'), 'the .tgz is copied next to index.yaml so its download URL resolves (production emitted a .helm-packages/ URL)');
}

console.log('helm-release-2082.test.mjs: all assertions passed');

/**
 * Helm chart release logic, with injectable dependencies so it is testable.
 *
 * Why this was rewritten (issue #2082, finding F1):
 *   The previous implementation ran every git command as a bare
 *   `await $\`...\`` using command-stream, whose `$` does NOT throw on a
 *   non-zero exit code. The wrapping try/catch could therefore never fire.
 *
 *   In production `git checkout gh-pages` aborted ("Your local changes to the
 *   following files would be overwritten by checkout: helm/hive-mind/Chart.yaml")
 *   because gh-pages also carries the repository tree and the script had just
 *   rewritten Chart.yaml. The failure was swallowed, the script kept running on
 *   `main`, committed the index onto main, pushed an unchanged gh-pages ref
 *   ("Everything up-to-date"), and printed "released successfully!". The public
 *   Helm repository stayed at 0.38.8 (2025-12-11) for ~7 months of green builds.
 *
 * This version:
 *   - Runs every command through `runStrict`, restoring `set -e` semantics.
 *   - Publishes from an isolated `git worktree` instead of switching branches
 *     in the dirty release checkout, removing the failure at its source.
 *   - Copies the archive next to index.yaml so its download URL resolves.
 *   - Verifies the pushed index really contains the released version, so any
 *     future regression is a red build rather than a silent no-op.
 *
 * Uses only Node built-ins so it has no dependency on node_modules state.
 */

import { copyFileSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';

import { runCommand, runStrict } from './run-command.lib.mjs';

/** Git's well-known hash of the empty tree, used to create an orphan branch without a checkout. */
const EMPTY_TREE = '4b825dc642cb6eb9a060e54bf8d69288fbee4904';

export const DEFAULT_CHART_DIR = 'helm/hive-mind';
export const DEFAULT_PACKAGE_DIR = '.helm-packages';
export const DEFAULT_WORKTREE_DIR = '.helm-gh-pages';
export const PUBLISH_BRANCH = 'gh-pages';

/**
 * Read the chart name out of a Chart.yaml document.
 * @param {string} chartYaml
 * @returns {string}
 */
export function parseChartName(chartYaml) {
  const match = chartYaml.match(/^name:\s*(\S+)/m);
  if (!match) {
    throw new Error('Could not determine chart name from Chart.yaml');
  }
  return match[1];
}

/**
 * Set `version` and `appVersion` in a Chart.yaml document.
 * @param {string} chartYaml
 * @param {string} version
 * @returns {string}
 */
export function updateChartVersion(chartYaml, version) {
  return chartYaml.replace(/^appVersion: .*/m, `appVersion: "${version}"`).replace(/^version: .*/m, `version: ${version}`);
}

/**
 * Whether a Helm repository index lists the given chart version.
 *
 * Matches only standalone `version:` keys, so `apiVersion:` and `appVersion:`
 * cannot produce a false positive.
 *
 * @param {string} indexYaml
 * @param {string} version
 * @returns {boolean}
 */
export function indexContainsVersion(indexYaml, version) {
  const escaped = version.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp(`^\\s*-?\\s*version:\\s*["']?${escaped}["']?\\s*$`, 'm').test(indexYaml);
}

/**
 * Package and publish the Helm chart to the gh-pages branch.
 *
 * @param {object} opts
 * @param {string} opts.version
 * @param {string} opts.helmRepoUrl
 * @param {string} opts.githubActor
 * @param {string} [opts.chartDir]
 * @param {string} [opts.packageDir]
 * @param {string} [opts.worktreeDir]
 * @param {typeof runCommand} [opts.runner] Soft runner; failures become throws via runStrict.
 * @param {object} [opts.fs] Injectable filesystem (readFileSync/writeFileSync/existsSync/copyFileSync/mkdirSync/rmSync).
 * @param {Console} [opts.logger]
 * @param {boolean} [opts.verbose]
 * @returns {Promise<{published: boolean, version: string, chartName: string, archive: string}>}
 */
export async function releaseHelmChart({ version, helmRepoUrl, githubActor, chartDir = DEFAULT_CHART_DIR, packageDir = DEFAULT_PACKAGE_DIR, worktreeDir = DEFAULT_WORKTREE_DIR, runner = runCommand, fs = { readFileSync, writeFileSync, existsSync, copyFileSync, mkdirSync, rmSync }, logger = console, verbose = false }) {
  if (!version) {
    throw new Error('Version is required');
  }

  const strict = (command, args) => runStrict(command, args, { runner, verbose, logger });
  const soft = (command, args) => runner(command, args, { verbose, logger });
  const chartPath = `${chartDir}/Chart.yaml`;

  logger.log(`Releasing Helm chart version ${version}...`);

  await strict('git', ['config', 'user.name', githubActor]);
  await strict('git', ['config', 'user.email', `${githubActor}@users.noreply.github.com`]);

  // Update Chart.yaml. Note this dirties the release checkout — which is
  // precisely why publishing must happen in a separate worktree below.
  logger.log(`Updating ${chartPath} to version ${version}...`);
  const chartYaml = fs.readFileSync(chartPath, 'utf8');
  const chartName = parseChartName(chartYaml);
  fs.writeFileSync(chartPath, updateChartVersion(chartYaml, version));

  logger.log('Linting Helm chart...');
  await strict('helm', ['lint', chartDir]);

  logger.log('Packaging Helm chart...');
  fs.mkdirSync(packageDir, { recursive: true });
  await strict('helm', ['package', chartDir, '-d', packageDir]);

  const archive = `${chartName}-${version}.tgz`;
  const archivePath = `${packageDir}/${archive}`;
  if (!fs.existsSync(archivePath)) {
    throw new Error(`helm package did not produce ${archivePath}`);
  }

  // Create gh-pages on the remote if it does not exist yet. Done with plumbing
  // so the release checkout is never touched.
  const branchExists = await soft('git', ['ls-remote', '--exit-code', '--heads', 'origin', PUBLISH_BRANCH]);
  if (branchExists.code !== 0) {
    logger.log(`Creating ${PUBLISH_BRANCH} branch...`);
    const commit = await strict('git', ['commit-tree', EMPTY_TREE, '-m', `Initialize ${PUBLISH_BRANCH} branch for Helm charts`]);
    await strict('git', ['push', 'origin', `${commit.stdout.trim()}:refs/heads/${PUBLISH_BRANCH}`]);
  }

  await strict('git', ['fetch', 'origin', `+refs/heads/${PUBLISH_BRANCH}:refs/remotes/origin/${PUBLISH_BRANCH}`]);

  try {
    logger.log(`Publishing from an isolated worktree at ${worktreeDir}...`);
    await strict('git', ['worktree', 'add', '--force', '-B', PUBLISH_BRANCH, worktreeDir, `origin/${PUBLISH_BRANCH}`]);

    // The archive must sit next to index.yaml, otherwise the generated download
    // URL points at a path that does not exist on GitHub Pages.
    fs.copyFileSync(archivePath, `${worktreeDir}/${archive}`);

    const indexPath = `${worktreeDir}/index.yaml`;
    const indexArgs = ['repo', 'index', worktreeDir, '--url', helmRepoUrl];
    if (fs.existsSync(indexPath)) {
      // Merging preserves the `created` timestamps of previously published charts.
      indexArgs.push('--merge', indexPath);
    }
    await strict('helm', indexArgs);

    await strict('git', ['-C', worktreeDir, 'add', '-f', '--', 'index.yaml', archive]);

    const commitResult = await soft('git', ['-C', worktreeDir, 'commit', '-m', `Release Helm chart version ${version}`]);
    if (commitResult.code !== 0) {
      logger.log('No changes to commit');
    }

    await strict('git', ['-C', worktreeDir, 'push', 'origin', `HEAD:${PUBLISH_BRANCH}`]);
  } finally {
    await soft('git', ['worktree', 'remove', '--force', worktreeDir]);
  }

  // Verify the push actually landed. Reading the index back out of the remote
  // ref is immediate and authoritative, unlike fetching the Pages URL which is
  // subject to CDN propagation lag.
  logger.log(`Verifying ${chartName}@${version} is present in the published index...`);
  await strict('git', ['fetch', 'origin', `+refs/heads/${PUBLISH_BRANCH}:refs/remotes/origin/${PUBLISH_BRANCH}`]);
  const publishedIndex = await strict('git', ['show', `origin/${PUBLISH_BRANCH}:index.yaml`]);
  if (!indexContainsVersion(publishedIndex.stdout, version)) {
    throw new Error(`Helm release verification failed: version ${version} is not present in the published index.yaml on ${PUBLISH_BRANCH}`);
  }

  logger.log(`Helm chart version ${version} released successfully!`);
  return { published: true, version, chartName, archive };
}

#!/usr/bin/env node

/**
 * Helm chart release script
 * Usage: node scripts/helm-release.mjs --release-version <version>
 *   release-version: Version number (e.g., 1.0.0)
 *
 * This script packages and publishes the Helm chart to the gh-pages branch.
 * It expects Helm to be installed and Git to be configured.
 *
 * The logic lives in scripts/helm-release.lib.mjs so it can be unit-tested
 * (see tests/helm-release-2082.test.mjs). This file only parses arguments.
 *
 * Set HIVE_MIND_CI_VERBOSE=1 to trace every command and its exit code.
 */

import { isVerbose } from './run-command.lib.mjs';
import { releaseHelmChart } from './helm-release.lib.mjs';

import { ensureUseM } from '../src/use-m-bootstrap.lib.mjs';

const use = await ensureUseM();
const { makeConfig } = await use('lino-arguments');

// Note: Using --release-version instead of --version to avoid conflict with yargs' built-in --version flag
const config = makeConfig({
  yargs: ({ yargs, getenv }) =>
    yargs
      .option('release-version', {
        type: 'string',
        default: getenv('VERSION', ''),
        describe: 'Version number (e.g., 1.0.0)',
      })
      .option('helm-repo-url', {
        type: 'string',
        default: getenv('HELM_REPO_URL', 'https://link-assistant.github.io/hive-mind'),
        describe: 'Helm repository URL',
      })
      .option('github-actor', {
        type: 'string',
        default: getenv('GITHUB_ACTOR', 'github-actions'),
        describe: 'GitHub username for Git commits',
      })
      .option('verbose', {
        type: 'boolean',
        default: isVerbose(),
        describe: 'Trace every command and its exit code',
      }),
});

const { releaseVersion: version, helmRepoUrl, githubActor, verbose } = config;

if (!version) {
  console.error('Error: Version is required');
  console.error('Usage: node scripts/helm-release.mjs --release-version <version>');
  process.exit(1);
}

try {
  await releaseHelmChart({ version, helmRepoUrl, githubActor, verbose });
} catch (error) {
  console.error('Error releasing Helm chart:', error.message);
  process.exit(1);
}

