/**
 * @hive-mind-test-suite default
 *
 * Regression coverage for issue #2082, finding F6.
 *
 * A GitHub Actions job without `timeout-minutes` inherits the default limit of
 * 360 minutes. A job that hangs — waiting on a prompt, a dead network socket, a
 * runaway test — therefore burns six hours of runner time before it is killed,
 * and reports as a generic failure that looks nothing like a hang. 21 of the 25
 * jobs in this repository had no timeout.
 *
 * docs/CI-CD-BEST-PRACTICES.md requires an explicit timeout on every job.
 * Nothing off the shelf enforces this: the zizmor request (zizmorcore/zizmor#1023)
 * and the actionlint request (rhysd/actionlint#49) are both still open. So this
 * test is the enforcement.
 *
 * Note the caveat that makes a naive version of this check wrong: a job that
 * calls a reusable workflow with `uses:` does NOT support `timeout-minutes` —
 * the timeout must be set inside the called workflow. Demanding one there would
 * replace a false negative with a false positive.
 *
 * @see https://github.com/link-assistant/hive-mind/issues/2082
 */

import assert from 'node:assert/strict';
import { readdirSync, readFileSync } from 'node:fs';
import path from 'node:path';

import { findJobs, findJobsMissingTimeout } from '../scripts/workflow-lint.lib.mjs';

// --- The scanner ----------------------------------------------------------

{
  const yaml = `name: Example
on: push
jobs:
  build:
    runs-on: ubuntu-latest
    timeout-minutes: 10
    steps:
      - run: echo build
  test:
    runs-on: ubuntu-latest
    steps:
      - run: echo test
`;

  const jobs = findJobs(yaml);
  assert.deepEqual(
    jobs.map(job => job.name),
    ['build', 'test'],
    'every job is found'
  );
  assert.equal(jobs[0].timeoutMinutes, 10, 'an explicit timeout is read');
  assert.equal(jobs[1].timeoutMinutes, null, 'a missing timeout is reported as null');
  assert.equal(jobs[1].line, 9, 'the job is reported at its own line so the message is actionable');

  assert.deepEqual(
    findJobsMissingTimeout(yaml).map(job => job.name),
    ['test'],
    'only the job without a timeout is reported'
  );
}

{
  // The false-positive trap: `timeout-minutes` is not valid on a reusable-workflow
  // caller, so requiring it there would be a bug in this check.
  const yaml = `jobs:
  call:
    uses: ./.github/workflows/other.yml
    secrets: inherit
`;
  assert.deepEqual(findJobsMissingTimeout(yaml), [], 'a job that calls a reusable workflow is exempt — timeout-minutes is not supported there');
  assert.equal(findJobs(yaml)[0].reusable, true, 'the caller is identified as reusable');
}

{
  // A `uses:` on a *step* is an action, not a reusable workflow: the job still
  // needs a timeout. Getting this wrong would silently exempt almost everything.
  const yaml = `jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v5
      - run: echo hi
`;
  assert.deepEqual(
    findJobsMissingTimeout(yaml).map(job => job.name),
    ['build'],
    'a step-level `uses:` must not exempt the job'
  );
  assert.equal(findJobs(yaml)[0].reusable, false, 'a job whose steps use actions is not a reusable-workflow caller');
}

{
  // `jobs:` keys must not be confused with other top-level mappings.
  const yaml = `on:
  push:
    branches: [main]
env:
  FOO: bar
jobs:
  only:
    runs-on: ubuntu-latest
    timeout-minutes: 5
`;
  assert.deepEqual(
    findJobs(yaml).map(job => job.name),
    ['only'],
    'keys under `on:` and `env:` are not mistaken for jobs'
  );
}

// --- Every job in this repository has a timeout ---------------------------

{
  const workflowDir = path.join(process.cwd(), '.github', 'workflows');
  const files = readdirSync(workflowDir).filter(file => file.endsWith('.yml') || file.endsWith('.yaml'));

  assert.ok(files.length > 0, 'workflow files are found — an empty glob would make this test vacuous');

  const offenders = [];
  let jobCount = 0;
  for (const file of files) {
    const yaml = readFileSync(path.join(workflowDir, file), 'utf8');
    jobCount += findJobs(yaml).length;
    for (const job of findJobsMissingTimeout(yaml)) {
      offenders.push(`${file}:${job.line} job "${job.name}"`);
    }
  }

  assert.ok(jobCount > 1, 'jobs are actually parsed — a parser that finds nothing would pass vacuously');
  assert.deepEqual(offenders, [], `every job must set timeout-minutes (see docs/CI-CD-BEST-PRACTICES.md).\nMissing on:\n  ${offenders.join('\n  ')}`);
}

console.log('ci-workflow-timeouts-2082.test.mjs: all assertions passed');

/**
 * Structural checks for GitHub Actions workflow files.
 *
 * Why this exists (issue #2082, finding F6):
 *   A job without `timeout-minutes` inherits GitHub's 360-minute default, so a
 *   hung job burns six hours of runner time and then reports as a generic
 *   failure. docs/CI-CD-BEST-PRACTICES.md requires an explicit timeout on every
 *   job, but nothing enforced it and 21 of 25 jobs had none.
 *
 *   No off-the-shelf linter covers this: zizmorcore/zizmor#1023 and
 *   rhysd/actionlint#49 are both open. Hence this check.
 *
 * The scanner is deliberately line-based rather than a real YAML parse: js-yaml
 * is only a transitive dependency here, and these checks must keep working when
 * node_modules is in an unknown state (the same constraint that shaped
 * scripts/run-command.lib.mjs). Workflow files are machine-written and uniformly
 * indented, so scanning at fixed indentation is reliable; the tests pin the
 * cases where it could go wrong.
 */

/**
 * A job declared in a workflow file.
 * @typedef {object} WorkflowJob
 * @property {string} name
 * @property {number} line 1-indexed line where the job is declared.
 * @property {number|null} timeoutMinutes
 * @property {boolean} reusable Whether the job calls a reusable workflow.
 */

/**
 * List the jobs declared in a workflow document.
 *
 * @param {string} yaml
 * @returns {WorkflowJob[]}
 */
export function findJobs(yaml) {
  const lines = String(yaml || '').split('\n');
  const jobs = [];

  let inJobs = false;
  let current = null;

  for (let index = 0; index < lines.length; index++) {
    const line = lines[index];

    // A top-level key ends the `jobs:` mapping.
    if (/^\S/.test(line)) {
      inJobs = /^jobs:\s*(#.*)?$/.test(line);
      current = null;
      continue;
    }

    if (!inJobs) {
      continue;
    }

    // A job name: exactly two spaces of indentation.
    const jobMatch = line.match(/^ {2}([A-Za-z_][A-Za-z0-9_-]*):\s*(#.*)?$/);
    if (jobMatch) {
      current = { name: jobMatch[1], line: index + 1, timeoutMinutes: null, reusable: false };
      jobs.push(current);
      continue;
    }

    if (!current) {
      continue;
    }

    // Job-level keys: exactly four spaces. Anything deeper belongs to a step,
    // which is why a step's `uses:` cannot be mistaken for a reusable-workflow
    // call and a step's `timeout-minutes:` cannot satisfy the job.
    const keyMatch = line.match(/^ {4}([a-z-]+):\s*(.*)$/);
    if (!keyMatch) {
      continue;
    }

    if (keyMatch[1] === 'timeout-minutes') {
      const value = Number.parseInt(keyMatch[2], 10);
      current.timeoutMinutes = Number.isNaN(value) ? null : value;
    } else if (keyMatch[1] === 'uses') {
      current.reusable = true;
    }
  }

  return jobs;
}

/**
 * Jobs that must declare `timeout-minutes` but do not.
 *
 * Jobs that call a reusable workflow are exempt: GitHub does not support
 * `timeout-minutes` on them, so the timeout has to live in the called workflow.
 * Reporting those would trade a false negative for a false positive.
 *
 * @param {string} yaml
 * @returns {WorkflowJob[]}
 */
export function findJobsMissingTimeout(yaml) {
  return findJobs(yaml).filter(job => !job.reusable && job.timeoutMinutes === null);
}

/**
 * @hive-mind-test-suite default
 *
 * Regression coverage for issue #2082, finding F4.
 *
 * `scripts/version-and-commit.mjs` ran every git command as a bare
 * `await $\`...\``. command-stream's `$` resolves with `.code` instead of
 * throwing, so the wrapping try/catch never fired — the same defect as F1 in
 * scripts/helm-release.mjs.
 *
 * The consequence here is worse than a no-op. `git push origin main` is racy by
 * construction: the release workflow pushes the version bump to main while other
 * runs and merges push to the same branch. When the push is rejected as
 * non-fast-forward, the old code printed "Version bump committed and pushed to
 * main", set `version_committed=true`, and exited 0 — handing the downstream
 * publish job a version that exists only in the runner's local checkout.
 *
 * These tests pin:
 *   1. a failing command aborts, rather than reporting a successful bump;
 *   2. a rejected push is retried on top of the new remote HEAD;
 *   3. `version_committed=true` is only ever emitted after the push really landed.
 *
 * @see https://github.com/link-assistant/hive-mind/issues/2082
 */

import assert from 'node:assert/strict';

import { CommandFailedError } from '../scripts/run-command.lib.mjs';
import { pushWithRebaseRetry, versionAndCommit } from '../scripts/version-and-commit.lib.mjs';

const REJECTED = {
  code: 1,
  stdout: '',
  stderr: " ! [rejected]        main -> main (fetch first)\nerror: failed to push some refs to 'https://github.com/link-assistant/hive-mind'\n",
};

/**
 * Build a recording runner.
 *
 * @param {object} [options]
 * @param {(command: string, args: string[], callIndex: number) => object|null} [options.respond]
 *   Return a result object to override the default success, or null for success.
 */
function createHarness({ respond = () => null, status = ' M package.json\n', version = '2.9.0' } = {}) {
  const calls = [];
  const outputs = {};
  let index = 0;

  const runner = async (command, args = []) => {
    const key = [command, ...args].join(' ');
    calls.push(key);
    const override = respond(command, args, index++);
    if (override) {
      return { stdout: '', stderr: '', ...override };
    }
    if (key === 'git status --porcelain') {
      return { code: 0, stdout: status, stderr: '' };
    }
    if (key.startsWith('git rev-parse')) {
      return { code: 0, stdout: 'abc123\n', stderr: '' };
    }
    return { code: 0, stdout: '', stderr: '' };
  };

  return {
    calls,
    outputs,
    runner,
    output: (key, value) => {
      outputs[key] = value;
    },
    readVersion: () => version,
    logger: { log() {}, error() {} },
  };
}

const run = (harness, overrides = {}) =>
  versionAndCommit({
    mode: 'changeset',
    runner: harness.runner,
    output: harness.output,
    readVersion: harness.readVersion,
    countChangesets: () => 1,
    logger: harness.logger,
    sleeper: async () => {},
    ...overrides,
  });

// --- 1. A failing command aborts the run ----------------------------------

{
  // `npm run changeset:version` fails: no commit, no push, no green output.
  const harness = createHarness({
    respond: (command, args) => (command === 'npm' && args.includes('changeset:version') ? { code: 1 } : null),
  });

  await assert.rejects(() => run(harness), CommandFailedError, 'a failing version bump must abort instead of continuing to commit and push');

  assert.ok(!harness.calls.some(call => call.startsWith('git push')), 'nothing is pushed after the version bump failed');
  assert.notEqual(harness.outputs.version_committed, 'true', 'version_committed must not be set after a failed bump');
}

{
  const harness = createHarness({
    respond: command => (command === 'git' ? null : { code: 0 }),
    status: '',
  });
  await run(harness);
  assert.equal(harness.outputs.version_committed, 'false', 'a clean tree reports no commit');
  assert.ok(!harness.calls.some(call => call.startsWith('git push')), 'a clean tree pushes nothing');
}

// --- 2. A rejected push is rebased and retried ----------------------------

{
  // The production race: another run pushed to main between our fetch and push.
  let pushes = 0;
  const harness = createHarness({
    respond: (command, args) => {
      if (command === 'git' && args[0] === 'push') {
        pushes += 1;
        return pushes === 1 ? REJECTED : null;
      }
      return null;
    },
  });

  await run(harness);

  assert.equal(pushes, 2, 'a rejected push is retried');
  const firstPush = harness.calls.indexOf('git push origin main');
  const rebase = harness.calls.findIndex(call => call.startsWith('git pull --rebase'));
  assert.ok(rebase > firstPush, 'the retry rebases onto the new remote HEAD before pushing again — a bare retry would be rejected identically');
  assert.equal(harness.outputs.version_committed, 'true', 'a push that succeeds on retry is a successful bump');
}

{
  // A push that never succeeds must fail the job loudly.
  const harness = createHarness({ respond: (command, args) => (command === 'git' && args[0] === 'push' ? REJECTED : null) });

  await assert.rejects(() => run(harness), CommandFailedError, 'a push that is rejected on every attempt must fail the job — this is what silently went green in production');

  assert.notEqual(harness.outputs.version_committed, 'true', 'version_committed must never be true when the push did not land');
}

// --- 3. pushWithRebaseRetry in isolation ----------------------------------

{
  const attempts = [];
  const runner = async (command, args = []) => {
    const key = [command, ...args].join(' ');
    attempts.push(key);
    return key === 'git push origin main' && attempts.filter(a => a.startsWith('git push')).length < 3 ? REJECTED : { code: 0, stdout: '', stderr: '' };
  };

  const result = await pushWithRebaseRetry({ runner, branch: 'main', sleeper: async () => {}, logger: { log() {}, error() {} } });
  assert.equal(result.attempt, 3, 'the push succeeds on the third attempt');

  await assert.rejects(
    () =>
      pushWithRebaseRetry({
        runner: async () => REJECTED,
        branch: 'main',
        maxAttempts: 2,
        sleeper: async () => {},
        logger: { log() {}, error() {} },
      }),
    CommandFailedError,
    'exhausting the retries throws rather than returning quietly'
  );
}

console.log('version-and-commit-2082.test.mjs: all assertions passed');

#!/usr/bin/env node
import { ensureUseM } from '../src/use-m-bootstrap.lib.mjs';

/**
 * Version packages and commit to main
 * Usage: node scripts/version-and-commit.mjs --mode <changeset|instant> [--bump-type <type>] [--description <desc>]
 *   changeset: Run changeset version
 *   instant: Run instant version bump with bump_type (patch|minor|major) and optional description
 *
 * The logic lives in scripts/version-and-commit.lib.mjs so it can be unit-tested
 * (see tests/version-and-commit-2082.test.mjs). This file only parses arguments.
 *
 * Set HIVE_MIND_CI_VERBOSE=1 to trace every command and its exit code.
 *
 * Uses link-foundation libraries:
 * - use-m: Dynamic package loading without package.json dependencies
 * - lino-arguments: Unified configuration from CLI args, env vars, and .lenv files
 */

import { appendFileSync, readdirSync } from 'node:fs';

import { isVerbose } from './run-command.lib.mjs';
import { versionAndCommit } from './version-and-commit.lib.mjs';

// Load use-m dynamically
const use = await ensureUseM();

// Import link-foundation libraries
const { makeConfig } = await use('lino-arguments');

// Parse CLI arguments using lino-arguments
const config = makeConfig({
  yargs: ({ yargs, getenv }) =>
    yargs
      .option('mode', {
        type: 'string',
        default: getenv('MODE', 'changeset'),
        describe: 'Version mode: changeset or instant',
        choices: ['changeset', 'instant'],
      })
      .option('bump-type', {
        type: 'string',
        default: getenv('BUMP_TYPE', ''),
        describe: 'Version bump type for instant mode: major, minor, or patch',
      })
      .option('description', {
        type: 'string',
        default: getenv('DESCRIPTION', ''),
        describe: 'Description for instant version bump',
      }),
});

const { mode, bumpType, description } = config;

// Debug: Log parsed configuration
console.log('Parsed configuration:', {
  mode,
  bumpType,
  description: description || '(none)',
});

// Detect if positional arguments were used (common mistake)
const args = process.argv.slice(2);
if (args.length > 0 && !args[0].startsWith('--')) {
  console.error('Error: Positional arguments detected!');
  console.error('Command line arguments:', args);
  console.error('');
  console.error('This script requires named arguments (--mode, --bump-type, --description).');
  console.error('Usage:');
  console.error('  Changeset mode:');
  console.error('    node scripts/version-and-commit.mjs --mode changeset');
  console.error('  Instant mode:');
  console.error('    node scripts/version-and-commit.mjs --mode instant --bump-type <major|minor|patch> [--description <desc>]');
  console.error('');
  console.error('Examples:');
  console.error('  node scripts/version-and-commit.mjs --mode instant --bump-type patch --description "Fix bug"');
  console.error('  node scripts/version-and-commit.mjs --mode changeset');
  process.exit(1);
}

// Validation: Ensure mode is set correctly
if (mode !== 'changeset' && mode !== 'instant') {
  console.error(`Invalid mode: "${mode}". Expected "changeset" or "instant".`);
  console.error('Command line arguments:', process.argv.slice(2));
  process.exit(1);
}

// Validation: Ensure bump type is provided for instant mode
if (mode === 'instant' && !bumpType) {
  console.error('Error: --bump-type is required for instant mode');
  console.error('Usage: node scripts/version-and-commit.mjs --mode instant --bump-type <major|minor|patch> [--description <desc>]');
  process.exit(1);
}

/**
 * Append to GitHub Actions output file
 * @param {string} key
 * @param {string} value
 */
function setOutput(key, value) {
  const outputFile = process.env.GITHUB_OUTPUT;
  if (outputFile) {
    console.log(`Setting GitHub output: ${key}=${value}`);
    appendFileSync(outputFile, `${key}=${value}\n`);
    console.log(`Output written to ${outputFile}`);
  } else {
    console.log(`GITHUB_OUTPUT not set, would have set: ${key}=${value}`);
  }
}

/**
 * Count changeset files (excluding README.md)
 */
function countChangesets() {
  try {
    return readdirSync('.changeset').filter(f => f.endsWith('.md') && f !== 'README.md').length;
  } catch {
    return 0;
  }
}

try {
